import json,re,hashlib
R=Path(__file__).resolve().parents[2];P=R/'public';M=json.loads((R/'scripts/project-sources/axion-lettering-font.json').read_text())
css='''@font-face{font-family:AxionButtonDisplay;src:url("FONT_WOFF") format("woff2");font-display:block}.axion-type-tester .type-preview{font-family:AxionButtonDisplay,sans-serif;color:#fff;background:#0000ff;line-height:1.4;letter-spacing:var(--type-tracking,0em);padding:28px 24px;min-height:240px;font-kerning:none;font-variant-ligatures:none}.axion-type-tester textarea{min-height:100px}.axion-type-controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}.axion-type-controls label{display:flex;justify-content:space-between;gap:16px}.axion-type-controls input[type=range]{width:100%;accent-color:#0000ff}.axion-type-tester .type-status{max-width:none}.axion-type-tester .axion-glyphs{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:24px 0}.axion-type-tester button{font:12px/1.4 "IBM Plex Mono",monospace;color:inherit;background:transparent;border:1px solid #777;padding:12px 16px;border-radius:0;min-height:44px}.axion-type-tester button:hover{background:#11110f;color:#ece9e3}.axion-type-tester .axion-font-downloads{display:flex;flex-wrap:wrap;gap:24px;font:12px/1.5 "IBM Plex Mono",monospace;margin:24px 0}.axion-font-downloads a{border-bottom:1px solid currentColor;padding:10px 0}.axion-type-tester :focus-visible{outline-color:#0000ff}.axion-type-tester .type-preview:focus-visible{outline:2px solid #0000ff;outline-offset:5px}@media(max-width:600px){.axion-type-controls{grid-template-columns:1fr;gap:0}.axion-type-tester .type-preview{padding:20px 16px;min-height:190px}.axion-type-tester{margin:28px 0}}
'''.replace('FONT_WOFF',M['woff2'])
