js='''(()=>{const section=document.querySelector('[data-axion-type-tester]');if(!section)return;const input=section.querySelector('textarea'),size=section.querySelector('[data-axion-size]'),spacing=section.querySelector('[data-axion-spacing]'),preview=section.querySelector('[data-type-preview]'),status=section.querySelector('[data-type-status]');const supported=new Set('AXION \\n');const it=document.documentElement.lang==='it';let ready=false;function update(){const value=input.value.toUpperCase(),missing=[...new Set([...value].filter(c=>!supported.has(c)))];preview.textContent=[...value].map(c=>supported.has(c)?c:'□').join('');preview.style.setProperty('--type-size',size.value+'px');preview.style.setProperty('--type-tracking',Number(spacing.value)/1000+'em');section.querySelector('[data-size-value]').textContent=size.value+' px';section.querySelector('[data-spacing-value]').textContent=(Number(spacing.value)/10).toFixed(1)+'%';input.setAttribute('aria-invalid',String(missing.length>0));if(ready)status.textContent=missing.length?(it?'Caratteri non disponibili: ':'Unavailable characters: ')+missing.join(' '):(it?'Anteprima dai tracciati originali. Lettere disponibili: A, X, I, O, N.':'Preview from the original outlines. Available letters: A, X, I, O, N.');}input.addEventListener('input',update);size.addEventListener('input',update);spacing.addEventListener('input',update);for(const b of section.querySelectorAll('[data-axion-glyph]'))b.addEventListener('click',()=>{const start=input.selectionStart,end=input.selectionEnd;input.setRangeText(b.dataset.axionGlyph,start,end,'end');update();input.focus({preventScroll:true});});section.querySelector('[data-axion-reset]').addEventListener('click',()=>{input.value='AXION';size.value='180';spacing.value='0';update();});update();document.fonts.load('48px AxionButtonDisplay','AXION').then(fonts=>{if(!fonts.length)throw Error('font');ready=true;preview.hidden=false;update();}).catch(()=>{status.textContent=it?'Anteprima non disponibile.':'Preview unavailable.';});})();'''
script='axion-type-tester-'+hashlib.sha256(js.encode()).hexdigest()[:12]+'.js';(P/'assets'/script).write_text(js)
for it in [False,True]:
 T=lambda a,b:a if it else b;pre='it/' if it else '';p=P/(pre+'work/axion-controllers/index.html');s=p.read_text()
