 title=T('Prova il lettering Axion','Try the Axion lettering');desc=T('Cinque lettere derivate dai comandi del controller. La versione web conserva curve, proporzioni e rapporti della composizione originale: A, X, I, O, N e spazio. Le minuscole usano le stesse forme maiuscole.','Five letters derived from controller inputs. The web version preserves the curves, proportions and relationships of the original composition: A, X, I, O, N and space. Lowercase input uses the same uppercase forms.')
 tester='<section class="type-tester axion-type-tester" data-axion-type-tester aria-labelledby="axion-tester-title"><h3 id="axion-tester-title">'+title+'</h3><p>'+desc+'</p><label for="axion-text">'+T('Scrivi la tua composizione','Write your composition')+'</label><textarea id="axion-text" maxlength="120" spellcheck="false" aria-describedby="axion-type-status">AXION</textarea><div class="axion-type-controls"><div><label for="axion-size">'+T('Dimensione','Size')+' <output data-size-value for="axion-size">180 px</output></label><input id="axion-size" data-axion-size type="range" min="32" max="240" value="180"></div><div><label for="axion-spacing">'+T('Spaziatura','Spacing')+' <output data-spacing-value for="axion-spacing">0.0%</output></label><input id="axion-spacing" data-axion-spacing type="range" min="-100" max="300" step="5" value="0"></div></div><div class="axion-glyphs" role="group" aria-label="'+T('Lettere disponibili','Available letters')+'">'+''.join('<button type="button" data-axion-glyph="'+c+'" aria-label="'+T('Inserisci ','Insert ')+c+'">'+c+'</button>' for c in 'AXION')+'<button type="button" data-axion-reset>'+T('Ripristina','Reset')+'</button></div><p class="type-status" id="axion-type-status" data-type-status role="status">'+T('Caricamento dell’anteprima…','Loading preview…')+'</p><div class="type-preview" data-type-preview hidden aria-label="'+T('Anteprima della composizione','Composition preview')+'"></div><div class="axion-font-downloads"><a href="'+M['ttf']+'" download>'+T('Scarica TTF','Download TTF')+' ↓</a><a href="'+M['woff2']+'" download>WOFF2 ↓</a></div><noscript><p>'+T('Attiva JavaScript per provare il lettering.','Enable JavaScript to try the lettering.')+'</p></noscript></section>'
 s,count=re.subn(r'(?:<div class="ax-lettering">.*?</div>|<section class="type-tester axion-type-tester".*?</section>)',lambda m:tester,s,flags=re.S);assert count==1
 s=s.replace(T('Un lettering sperimentale ricava le cinque lettere di AXION dalle forme dei comandi del controller. Le tavole originali sono state trasformate in un piccolo font display: questa versione contiene A, X, I, O, N e lo spazio.','Experimental lettering derives the five letters of AXION from controller input shapes. The original artwork has been adapted into a small display font: this version contains A, X, I, O, N and space.'),T('Un lettering sperimentale ricava le cinque lettere di AXION dalle forme dei comandi del controller. La composizione originale diventa un font display con una prova interattiva dedicata.','Experimental lettering derives the five letters of AXION from controller input shapes. The original composition becomes a display font with a dedicated interactive specimen.'))
